Scoping the key by `account_id` stops one account's keys from colliding with another's. Postgres treats NULLs as distinct, so requests without a key are unaffected.

Handler in `routes/orders.js`:

```js
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) " +
    "ON CONFLICT (account_id, idempotency_key) DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (row.sku !== req.body.sku || row.quantity !== Number(req.body.quantity)) return res.status(422).end();
  res.status(201).json(row);
});
```

